stmt.execute("CREATE TABLE users (id INT PRIMARY KEY, name VARCHAR(100) NOT NULL)");
stmt.execute("""
    CREATE TABLE user_profiles (
        user_id INT PRIMARY KEY REFERENCES users(id),
        bio VARCHAR(255)
    )
    """);
// Klucz obcy w tabeli 'podrzednej' (user_profiles) jest JEDNOCZESNIE
// jej kluczem GLOWNYM (PRIMARY KEY = FOREIGN KEY) - to gwarantuje,
// ze jeden uzytkownik moze miec NAJWYZEJ JEDEN profil.

stmt.execute("INSERT INTO users VALUES (1, 'Jan Kowalski')");
stmt.execute("INSERT INTO user_profiles VALUES (1, 'Lubie Jave i kawe')");

stmt.execute("CREATE TABLE authors (id INT PRIMARY KEY, name VARCHAR(100) NOT NULL)");
stmt.execute("""
    CREATE TABLE books (
        id INT PRIMARY KEY,
        title VARCHAR(150) NOT NULL,
        author_id INT REFERENCES authors(id)
    )
    """);
// authors -> books: relacja 1:N (jeden autor, wiele ksiazek).
// books -> authors: DOKLADNIE TA SAMA relacja, widziana odwrotnie: N:1.
// Klucz obcy author_id w tabeli 'wielu' (books) NIE musi byc unikalny -
// wiele wierszy books moze miec ten sam author_id.

stmt.execute("INSERT INTO authors VALUES (1, 'Andrzej Sapkowski')");
stmt.execute("INSERT INTO books VALUES (1, 'Wiedzmin', 1), (2, 'Miecz przeznaczenia', 1)");

System.out.println("=== TEST INTEGRALNOSCI REFERENCYJNEJ ===");
try {
    stmt.execute("INSERT INTO books VALUES (4, 'Ksiazka widmo', 999)");
    System.out.println("Wstawiono - to NIE powinno sie zdarzyc!");
} catch (SQLException e) {
    System.out.println("Baza odrzucila wstawienie (jak powinna): " + e.getMessage());
}
// Proba dodania ksiazki z nieistniejacym author_id (999) - baza
// ODRZUCA to automatycznie, dzieki ograniczeniu FOREIGN KEY.

stmt.execute("""
    CREATE TABLE products_categories (
        product_id INT REFERENCES products(id),
        category_id INT REFERENCES categories(id),
        PRIMARY KEY (product_id, category_id)
    )
    """);

// Laptop nalezy do DWOCH kategorii, mysz do dwoch innych
stmt.execute("INSERT INTO products_categories VALUES (1, 1)"); // Laptop - Elektronika
stmt.execute("INSERT INTO products_categories VALUES (1, 2)"); // Laptop - Praca zdalna
stmt.execute("INSERT INTO products_categories VALUES (2, 1)"); // Mysz - Elektronika
stmt.execute("INSERT INTO products_categories VALUES (2, 3)"); // Mysz - Akcesoria

